# Regenerate R/data.R from the dataset-specific documentation catalog.
records <- jsonlite::fromJSON(
  "data-raw/dataset-descriptions.json",
  simplifyVector = FALSE
)
paragraphs <- function(text) {
  blocks <- strsplit(text, "\n\n", fixed = TRUE)[[1]]
  unlist(lapply(seq_along(blocks), function(i) {
    c(if (i > 1) "#'", paste0("#' ", strwrap(blocks[i], width = 76)))
  }))
}
output <- c(
  "# Generated by data-raw/document-data.R; edit dataset-descriptions.json.",
  ""
)
for (x in records) {
  object_env <- new.env()
  load(file.path("data", paste0(x$name, ".rda")), object_env)
  has_structure <- "glycan_structure" %in%
    names(
      SummarizedExperiment::rowData(object_env[[x$name]])
    )
  source <- paste0(
    "GlycoPOST ",
    x$accession,
    ". ",
    x$table,
    ". ",
    "Study: \\url{https://doi.org/",
    x$doi,
    "}. ",
    "Repository: \\url{https://glycopost.glycosmos.org/entry/",
    x$accession,
    "}.",
    if (!is.null(x$source_url)) {
      paste0(" Quantitative source: \\url{", x$source_url, "}.")
    } else {
      ""
    },
    if (!is.null(x$annotation_source_url)) {
      paste0(" Annotation evidence: \\url{", x$annotation_source_url, "}.")
    } else {
      ""
    },
    if (!is.null(x$related_doi)) {
      paste0(" Related study: \\url{https://doi.org/", x$related_doi, "}.")
    } else {
      ""
    }
  )
  output <- c(
    output,
    paste0("#' ", x$title),
    "#'",
    paragraphs(x$description),
    "#'",
    "#' @details",
    paragraphs(x$details),
    "#'",
    paragraphs(x$annotation),
    "#'",
    "#' @format",
    paragraphs(paste0(
      "A [glyexp::",
      if (is.null(x$object_class)) "GlycomicSE" else x$object_class,
      "] with ",
      x$features,
      " features and ",
      x$observations,
      " observations. The abundance assay is in ",
      x$unit,
      ". ",
      if (has_structure) {
        "rowData includes a typed glycan_structure column; features without a supported structure are NA."
      } else {
        "rowData has no glycan_structure column because no feature has a supported structural annotation."
      }
    )),
    "#' @source",
    paragraphs(source),
    "#' @seealso [glyhub_data_conventions] for missing-value handling, annotations",
    "#'   and access to original measurements and source coordinates.",
    "#' @keywords datasets",
    paste0('"', x$name, '"'),
    ""
  )
}
writeLines(output, "R/data.R")
